design:
@import url("");
:root {
  xaicolorcanvas: 0a0a0a;
  xaicolorcanvassoft: 141414;
  xaicolorcanvascard: 191919;
  xaicolorprimary: ffffff;
  xaicolortextsecondary: rgba(255, 255, 255, 0.7);
  xaicolortextmuted: rgba(255, 255, 255, 0.4);
  xaicolortextdisabled: rgba(255, 255, 255, 0.25);
  xaibordersubtle: rgba(255, 255, 255, 0.08);
  xaiborderdefault: rgba(255, 255, 255, 0.15);
  xaiborderstrong: rgba(255, 255, 255, 0.25);
  xaiborderhover: rgba(255, 255, 255, 0.5);
  xaicolorfocus: 3b82f6;
  xaifontsans: "Inter", applesystem, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sansserif;
  xaifontmono: "Courier New", Courier, monospace;
  xairadiussharp: 0px;
  xairadiussoft: 4px;
  xairadiuspill: 9999px;
  xaispace1: 4px;
  xaispace2: 8px;
  xaispace3: 12px;
  xaispace4: 16px;
  xaispace5: 24px;
  xaispace6: 32px;
  xaispace7: 48px;
  xaispace8: 96px;
}
, ::before, ::after {
  boxsizing: borderbox;
  margin: 0;
  padding: 0;
}
html {
  backgroundcolor: var(xaicolorcanvas);
  color: var(xaicolorprimary);
  fontfamily: var(xaifontsans);
  fontsize: 16px;
  lineheight: 1.5;
  webkittextsizeadjust: 100%;
  textsizeadjust: 100%;
  webkitfontsmoothing: antialiased;
  mozosxfontsmoothing: grayscale;
  scrollbehavior: smooth;
}
body {
  backgroundcolor: var(xaicolorcanvas);
  color: var(xaicolorprimary);
  minheight: 100vh;
  display: flex;
  flexdirection: column;
  overflowx: hidden;
}
h1, h2, h3, h4, h5, h6 {
  fontweight: 300;
  color: var(xaicolorprimary);
  lineheight: 1.1;
  letterspacing: 0.03em;
}
h1 {
  fontsize: clamp(2.5rem, 6vw, 5.5rem);
  letterspacing: 0.04em;
  marginbottom: var(xaispace5);
}
h2 {
  fontsize: clamp(1.75rem, 4vw, 2.75rem);
  letterspacing: 0.03em;
  marginbottom: var(xaispace4);
}
h3 {
  fontsize: clamp(1.25rem, 3vw, 1.75rem);
  marginbottom: var(xaispace3);
}
h4 {
  fontsize: 1.25rem;
  marginbottom: var(xaispace2);
}
p {
  color: var(xaicolortextsecondary);
  fontsize: 1rem;
  lineheight: 1.6;
  marginbottom: var(xaispace4);
}
a {
  color: var(xaicolorprimary);
  textdecoration: none;
  transition: opacity 0.2s ease, bordercolor 0.2s ease;
}
a:hover {
  opacity: 0.8;
}
.xaimono {
  fontfamily: var(xaifontmono);
  fontsize: 0.875rem;
  letterspacing: 0.05em;
}
.xaicode {
  fontfamily: var(xaifontmono);
  backgroundcolor: var(xaicolorcanvassoft);
  border: 1px solid var(xaibordersubtle);
  padding: var(xaispace1) var(xaispace2);
  borderradius: var(xairadiussoft);
  fontsize: 0.85em;
  color: var(xaicolorprimary);
}
.xaicontainer {
  width: 100%;
  maxwidth: 1200px;
  marginleft: auto;
  marginright: auto;
  paddingleft: var(xaispace5);
  paddingright: var(xaispace5);
}
.xaigrid {
  display: grid;
  gridtemplatecolumns: repeat(12, minmax(0, 1fr));
  gap: var(xaispace5);
}
.xaicol12 {
  gridcolumn: span 12 / span 12;
}
.xaicol6 {
  gridcolumn: span 6 / span 6;
}
.xaicol4 {
  gridcolumn: span 4 / span 4;
}
.xaicol3 {
  gridcolumn: span 3 / span 3;
}
@media (maxwidth: 768px) {
  .xaigrid {
    gridtemplatecolumns: 1fr;
  }
  .xaicol6, .xaicol4, .xaicol3 {
    gridcolumn: span 12 / span 12;
  }
}
.xaiflex {
  display: flex;
}
.xaiflexrow {
  flexdirection: row;
}
.xaiflexcol {
  flexdirection: column;
}
.xaiitemscenter {
  alignitems: center;
}
.xaijustifybetween {
  justifycontent: spacebetween;
}
.xaijustifycenter {
  justifycontent: center;
}
.xaiheader {
  borderbottom: 1px solid var(xaibordersubtle);
  backgroundcolor: var(xaicolorcanvas);
  position: sticky;
  top: 0;
  zindex: 100;
}
.xainav {
  display: flex;
  alignitems: center;
  justifycontent: spacebetween;
  height: 64px;
}
.xailogo {
  fontfamily: var(xaifontsans);
  fontweight: 400;
  fontsize: 1.5rem;
  letterspacing: 0.05em;
}
.xainavlinks {
  display: flex;
  gap: var(xaispace5);
}
.xainavlink {
  fontsize: 0.875rem;
  color: var(xaicolortextsecondary);
  transition: color 0.2s ease;
}
.xainavlink:hover {
  color: var(xaicolorprimary);
}
.xaibtn {
  display: inlineflex;
  alignitems: center;
  justifycontent: center;
  fontfamily: var(xaifontmono);
  fontsize: 13px;
  fontweight: 400;
  texttransform: uppercase;
  letterspacing: 1.4px;
  color: var(xaicolorprimary);
  backgroundcolor: transparent;
  border: 1px solid var(xaiborderstrong);
  padding: var(xaispace3) var(xaispace5);
  borderradius: var(xairadiuspill);
  cursor: pointer;
  transition: bordercolor 0.2s ease, opacity 0.2s ease, backgroundcolor 0.2s ease, color 0.2s ease;
}
.xaibtn:hover {
  bordercolor: var(xaicolorprimary);
}
.xaibtn:active {
  opacity: 0.7;
}
.xaibtnprimary {
  backgroundcolor: var(xaicolorprimary);
  color: var(xaicolorcanvas);
  bordercolor: var(xaicolorprimary);
}
.xaibtnprimary:hover {
  backgroundcolor: transparent;
  color: var(xaicolorprimary);
  bordercolor: var(xaiborderstrong);
}
.xaibtnsm {
  padding: var(xaispace2) var(xaispace4);
  fontsize: 11px;
}
.xaicard {
  backgroundcolor: var(xaicolorcanvascard);
  border: 1px solid var(xaiborderdefault);
  borderradius: var(xairadiussharp);
  padding: var(xaispace5);
  transition: bordercolor 0.2s ease;
  display: flex;
  flexdirection: column;
}
.xaicard:hover {
  bordercolor: var(xaiborderstrong);
}
.xaicardeyebrow {
  display: inlineblock;
  fontfamily: var(xaifontmono);
  fontsize: 11px;
  texttransform: uppercase;
  letterspacing: 1px;
  color: var(xaicolortextmuted);
  marginbottom: var(xaispace2);
}
.xaicardtitle {
  fontsize: 1.5rem;
  marginbottom: var(xaispace3);
}
.xaicarddesc {
  color: var(xaicolortextsecondary);
  fontsize: 0.95rem;
  lineheight: 1.5;
}
.xaiformgroup {
  display: flex;
  flexdirection: column;
  gap: var(xaispace2);
  marginbottom: var(xaispace4);
}
.xailabel {
  fontfamily: var(xaifontmono);
  fontsize: 11px;
  texttransform: uppercase;
  letterspacing: 1px;
  color: var(xaicolortextmuted);
}
.xaiinput {
  width: 100%;
  backgroundcolor: var(xaicolorcanvassoft);
  border: 1px solid var(xaiborderdefault);
  borderradius: var(xairadiuspill);
  padding: var(xaispace3) var(xaispace4);
  color: var(xaicolorprimary);
  fontfamily: var(xaifontsans);
  fontsize: 15px;
  outline: none;
  transition: bordercolor 0.2s ease;
}
.xaiinput:focus {
  bordercolor: var(xaicolorfocus);
}
.xaiinput::placeholder {
  color: var(xaicolortextdisabled);
}
.xaiterminal {
  backgroundcolor: var(xaicolorcanvassoft);
  border: 1px solid var(xaiborderdefault);
  borderradius: var(xairadiussoft);
  fontfamily: var(xaifontmono);
  padding: var(xaispace4);
  overflowx: auto;
  marginbottom: var(xaispace5);
}
.xaiterminalheader {
  display: flex;
  gap: var(xaispace2);
  marginbottom: var(xaispace3);
}
.xaiterminaldot {
  width: 12px;
  height: 12px;
  borderradius: 50%;
  backgroundcolor: var(xaiborderstrong);
}
.xaiterminalline {
  fontsize: 13px;
  lineheight: 1.6;
  color: var(xaicolortextsecondary);
}
.xaiterminallineprompt {
  color: var(xaicolorprimary);
}
.xaiterminallineprompt::before {
  content: "$ ";
  color: var(xaicolortextmuted);
}
.xaifooter {
  bordertop: 1px solid var(xaibordersubtle);
  backgroundcolor: var(xaicolorcanvas);
  paddingtop: var(xaispace6);
  paddingbottom: var(xaispace6);
  margintop: auto;
}
.xaifootercontent {
  display: flex;
  alignitems: center;
  justifycontent: spacebetween;
}
@media (maxwidth: 600px) {
  .xaifootercontent {
    flexdirection: column;
    gap: var(xaispace4);
    textalign: center;
  }
}
.xaifootercopy {
  fontsize: 0.75rem;
  color: var(xaicolortextmuted);
  fontfamily: var(xaifontmono);
}
.xaifooterlinks {
  display: flex;
  gap: var(xaispace4);
}
.xaifooterlink {
  fontsize: 0.75rem;
  color: var(xaicolortextmuted);
  fontfamily: var(xaifontmono);
  texttransform: uppercase;
  letterspacing: 0.5px;
}
.xaifooterlink:hover {
  color: var(xaicolorprimary);
}
.xaihidden {
  display: none;
}
.xaitextcenter {
  textalign: center;
}
.xaitextright {
  textalign: right;
}
.xaitextleft {
  textalign: left;
}
.xaiwfull {
  width: 100%;
}
.xaihfull {
  height: 100%;
}
.xaimxauto {
  marginleft: auto;
  marginright: auto;
}
.xaimy5 {
  margintop: var(xaispace5);
  marginbottom: var(xaispace5);
}
.xaipy8 {
  paddingtop: var(xaispace8);
  paddingbottom: var(xaispace8);
}
.xaiopacity50 {
  opacity: 0.5;
}






